function difficultySummary(r){if(r.mode==='sequence')return '';const deck=difficultQuestions(r.answers,r.deck,r.config.target),errors=r.answers.filter(a=>!a.correct).length,slow=r.answers.filter(a=>a.correct&&r.config.target>0&&a.ms>r.config.target*1000).length;return `<div class="session-focus-summary"><div><b>${deck.length?'Seu próximo foco está aqui.':'Grupo concluído. Continue evoluindo.'}</b><p>${errors} ${errors===1?'erro':'erros'} · ${slow} ${slow===1?'acerto acima':'acertos acima'} da meta${r.config.trainingOrder!=='adaptive'?` · ${new Set(r.answers.map(questionKey)).size} itens diferentes praticados`:''}.</p></div>${deck.length?btn('Revisar '+deck.length+' itens','retry-difficult','secondary','repeat'):''}</div>`;}

